 flows: [
  {"id":"set-leech-log","title":"Set the leech log chat","desc":"Dump every leeched file into a channel.","steps":[{"screen":"main","press":"Config Variables","say":"Send /bsettings and open Config Variables."},{"screen":"cfg_1","press":"7","say":"Use the footer page numbers to jump to page 7."},{"screen":"cfg_7","press":"LEECH_LOG_CHAT","say":"LEECH_LOG_CHAT is on this page."},{"screen":"v_LEECH_LOG_CHAT","press":"Edit Value","say":"Edit Value arms a 60 s prompt for LEECH_LOG_CHAT."},{"screen":"e_LEECH_LOG_CHAT","reply":"-1001234567890","say":"Send the chat ID with the -100 prefix (add |topic_id for a forum topic). The bot deletes your message and redraws with the new value."}]},
  {"id":"add-session","title":"Add a premium session string (4 GB)","desc":"Enable 4 GB leech with a premium user session.","steps":[{"screen":"main","press":"Config Variables","say":"Send /bsettings and open Config Variables."},{"screen":"cfg_1","press":"13","say":"Use the footer page numbers to jump to page 13."},{"screen":"cfg_13","press":"USER_SESSION_STRING","say":"USER_SESSION_STRING is on this page."},{"screen":"v_USER_SESSION_STRING","press":"Edit Value","say":"Edit Value arms a 60 s prompt for USER_SESSION_STRING."},{"screen":"e_USER_SESSION_STRING","reply":"BQAbCdEfGhIjKlMnOpQrStUvWxYz0123456789abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789-_abcdefghijklmnopqrstuvwxyz0123456789","say":"Paste the Pyrogram session string of a premium account; it enables 4 GB uploads. The prompt warns that a restart is required."},{"screen":"d_USER_SESSION_STRING","press":"Close","say":"Restart the bot so the session takes effect, then close the menu."}]},
  {"id":"set-queue","title":"Limit simultaneous downloads","desc":"Cap parallel downloads and uploads with QUEUE_*.","steps":[{"screen":"main","press":"Config Variables","say":"Open Config Variables."},{"screen":"cfg_1","press":"10","say":"Jump to the page with the QUEUE_* variables."},{"screen":"cfg_10","press":"QUEUE_DOWNLOAD","say":"QUEUE_DOWNLOAD caps parallel downloading tasks (0 = unlimited)."},{"screen":"v_QUEUE_DOWNLOAD","press":"Edit Value","say":"Open the edit prompt."},{"screen":"e_QUEUE_DOWNLOAD","reply":"3","say":"Allow 3 downloads at a time; the rest wait in the queue."},{"screen":"d_QUEUE_DOWNLOAD","press":"Back","say":"Back to the same page to set QUEUE_UPLOAD."},{"screen":"cfg_10","press":"QUEUE_UPLOAD","say":"Now the upload cap."},{"screen":"v_QUEUE_UPLOAD","press":"Edit Value","say":"Open the edit prompt."},{"screen":"e_QUEUE_UPLOAD","reply":"2","say":"Two simultaneous uploads. Queued tasks start automatically."}]},
  {"id":"edit-ffmpeg","title":"Edit FFMPEG_CMDS","desc":"Define ffmpeg presets that users pick with -ff.","steps":[{"screen":"main","press":"Config Variables","say":"Send /bsettings and open Config Variables."},{"screen":"cfg_1","press":"3","say":"Use the footer page numbers to jump to page 3."},{"screen":"cfg_3","press":"FFMPEG_CMDS","say":"FFMPEG_CMDS is on this page."},{"screen":"v_FFMPEG_CMDS","press":"Edit Value","say":"Edit Value arms a 60 s prompt for FFMPEG_CMDS."},{"screen":"e_FFMPEG_CMDS","reply":"{'compress': ['-i mltb.mkv -c:v libx265 -crf 28 -preset fast -c:a copy mltb.mkv'], 'watermark': ['-i mltb.mkv -i wm.png -filter_complex overlay=10:10 -c:a copy mltb.mkv']}","say":"Send a dict of preset name to a list of ffmpeg argument strings; mltb.mkv is the input/output placeholder."}]},
  {"id":"toggle-module","title":"Disable a module","desc":"Switch RSS off to save CPU, then back on.","steps":[{"screen":"main","press":"Module Settings","say":"Module Settings holds the DISABLE_* switches and size limits."},{"screen":"mod","press":"On/Off Settings","say":"A check mark means the module is enabled."},{"screen":"tg_base","press":"✓ RSS","say":"Sets DISABLE_RSS = True and stops the RSS scheduler. The check mark disappears."},{"screen":"tg_DISABLE_RSS","press":"RSS","say":"Press again to re-enable; the scheduler starts again."},{"screen":"tg_base","press":"Back","say":"Back to Module Settings."}]},
  {"id":"private-files","title":"Upload rclone.conf and token.pickle","desc":"Provide rclone and Google Drive credentials.","steps":[{"screen":"main","press":"Private Files","say":"The dashboard lists which credential files exist."},{"screen":"priv_0","press":"Add/Delete File","say":"Starts a 60 s listener for a document or a file name."},{"screen":"pe_0","reply":"rclone.conf  [file attached]","say":"Attach rclone.conf as a document. The dashboard now shows it as Exists."},{"screen":"priv_1","press":"Add/Delete File","say":"Do it again for token.pickle."},{"screen":"pe_1","reply":"token.pickle  [file attached]","say":"Both files are saved; text with just a file name would delete one instead."}]},
  {"id":"tune-torrents","title":"Tune qBittorrent and aria2","desc":"Change engine options live.","steps":[{"screen":"main","press":"Qbit Settings","say":"Qbittorrent Options opens in view state."},{"screen":"qb_v0","press":"Edit","say":"Switch to edit state."},{"screen":"qb_e0","press":"1","say":"Option names are paged; use the footer numbers to find max_active_downloads."},{"screen":"qb_e1","press":"max_active_downloads","say":"Pick the option."},{"screen":"qbo_max_active_downloads","reply":"10","say":"Limit to 10 active downloads. The preference is pushed to qBittorrent and saved."},{"screen":"qb_e1","press":"Back","say":"Back to Bot Settings; aria2 works the same way."},{"screen":"main","press":"Aria2c Settings","say":"Open aria2c options."},{"screen":"ar_v0","press":"Add new key","say":"Add an option that is not listed, as key:value."},{"screen":"an_key","reply":"https-proxy-user:me:pass","say":"The key is applied with changeGlobalOption."}]},
  {"id":"auth-users","title":"Add sudo and authorized users","desc":"Grant access without editing config.py.","steps":[{"screen":"main","press":"Config Variables","say":"Open Config Variables."},{"screen":"cfg_1","press":"11","say":"Jump to the page with SUDO_USERS."},{"screen":"cfg_11","press":"SUDO_USERS","say":"SUDO_USERS can use /bsettings and admin commands."},{"screen":"v_SUDO_USERS","press":"Edit Value","say":"Open the edit prompt."},{"screen":"e_SUDO_USERS","reply":"123456789 987654321","say":"Space-separated IDs; the in-memory list is replaced right away."},{"screen":"d_SUDO_USERS","press":"Back","say":"Now authorize a chat."},{"screen":"cfg_11","press":"1","say":"Jump to the AUTHORIZED_CHATS page."},{"screen":"cfg_1","press":"AUTHORIZED_CHATS","say":"AUTHORIZED_CHATS takes chat IDs (chat|thread supported)."},{"screen":"v_AUTHORIZED_CHATS","press":"Edit Value","say":"Open the edit prompt."},{"screen":"e_AUTHORIZED_CHATS","reply":"-1001234567890 -1009876543210|5","say":"A restart is recommended for this variable."}]}
 ]
